function validate(input) {
  const [{ Customers = [], Contacts = [], Invoices = [] }] = input;
  const ids = new Set(), emails = new Set(), pairs = new Set(), invoices = new Set();
  for (const [id, , email] of Customers) {
    if (id === null) return 'Every customer needs a customer_id.';
    if (ids.has(id)) return `customer_id ${id} appears twice.`;
    if (email === null) return `Customer ${id} needs an email.`;
    if (emails.has(email.toLowerCase())) return `Email ${email} belongs to two customers.`;
    ids.add(id);
    emails.add(email.toLowerCase());
  }
  for (const [user, , email] of Contacts) {
    if (!ids.has(user)) return `Contact owner ${user} is not a customer.`;
    if (email === null) return 'Every contact needs a contact_email.';
    const key = `${user}|${email.toLowerCase()}`;
    if (pairs.has(key)) return `Customer ${user} lists ${email} twice.`;
    pairs.add(key);
  }
  for (const [id, price, user] of Invoices) {
    if (id === null) return 'Every invoice needs an invoice_id.';
    if (invoices.has(id)) return `invoice_id ${id} appears twice.`;
    if (price === null) return `Invoice ${id} needs a price.`;
    if (!ids.has(user)) return `Invoice ${id} belongs to unknown customer ${user}.`;
    invoices.add(id);
  }
  return null;
}

