function generate(rand, size) {
  const small = size === 'small';
  const int = n => Math.floor(rand() * n);
  const shuffle = list => { for (let i = list.length - 1; i > 0; i--) { const j = int(i + 1); [list[i], list[j]] = [list[j], list[i]]; } return list; };
  // People who can appear as customers or contacts; each has one email.
  const base = ['Alice', 'Bob', 'John', 'Alex', 'Jal', 'Omar', 'Meir', 'Sara'];
  const people = small
    ? base.map(name => [name, `${name.toLowerCase()}@leetcode.com`])
    : Array.from({ length: 800 }, (_, k) => [`Person${k}`, `person${k}@shop.com`]);
  shuffle(people);
  const customerCount = small ? int(6) : 400;
  const customerIds = shuffle(Array.from({ length: small ? 15 : 1000 }, (_, k) => k + 1)).slice(0, customerCount);
  const Customers = customerIds.map((id, k) => [id, people[k][0], people[k][1]]);
  const Contacts = [];
  const maxContacts = small ? int(9) : 2000;
  const seen = new Set();
  for (let tries = 0; Customers.length && Contacts.length < maxContacts && tries < maxContacts * 4; tries++) {
    const [owner, , ownEmail] = Customers[int(Customers.length)];
    const [name, email] = people[int(people.length)];
    const key = `${owner}|${email}`;
    if (email === ownEmail || seen.has(key)) continue;
    seen.add(key);
    Contacts.push([owner, name, email]);
  }
  const Invoices = [];
  if (Customers.length) {
    const invoiceIds = shuffle(Array.from({ length: small ? 99 : 5000 }, (_, k) => k + 1)).slice(0, small ? int(9) : 2000);
    for (const id of invoiceIds) Invoices.push([id, 10 * (1 + int(small ? 5 : 50)), Customers[int(Customers.length)][0]]);
  }
  return [{ Customers, Contacts, Invoices }];
}
